-- Student Portal / Employee Portal: dynamic student guidance content
-- Run this script in the Supabase SQL Editor before using the new screens.

create table if not exists public.student_guides (
  id bigint generated by default as identity primary key,
  title text not null check (length(trim(title)) > 0),
  details text not null check (length(trim(details)) > 0),
  sort_order integer not null default 1,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists student_guides_active_order_idx
  on public.student_guides (is_active, sort_order, id);

alter table public.student_guides enable row level security;

drop policy if exists "Published guidance is readable" on public.student_guides;
create policy "Published guidance is readable"
  on public.student_guides for select
  to anon, authenticated
  using (is_active = true);

-- Employee writes must use a trusted employee authorization mechanism.
-- Do not grant INSERT/UPDATE/DELETE to anon or expose a service-role key in the browser.


-- Initial published guidance content. Re-running this script will not create duplicates.
update public.student_guides set details = 'قبل بدء التسجيل، جهّز بياناتك الصحيحة كما تظهر في الوثائق الرسمية. أدخل الاسم ورقم الهوية ورقم الهاتف والمدرسة والفرع والبيانات المطلوبة دون أخطاء، وراجع جميع الحقول قبل إرسال الطلب. لا تستخدم بيانات طالب آخر ولا ترسل كلمة المرور لأي شخص. بعد نجاح التسجيل، احتفظ ببيانات الدخول في مكان آمن وتأكد من إمكانية الوصول إلى رقم الهاتف المسجّل عند الحاجة إلى التحقق.', sort_order = 1, is_active = true, updated_at = now() where title = 'تعليمات تسجيل طالب جديد';
insert into public.student_guides (title, details, sort_order, is_active)
select 'تعليمات تسجيل طالب جديد', 'قبل بدء التسجيل، جهّز بياناتك الصحيحة كما تظهر في الوثائق الرسمية. أدخل الاسم ورقم الهوية ورقم الهاتف والمدرسة والفرع والبيانات المطلوبة دون أخطاء، وراجع جميع الحقول قبل إرسال الطلب. لا تستخدم بيانات طالب آخر ولا ترسل كلمة المرور لأي شخص. بعد نجاح التسجيل، احتفظ ببيانات الدخول في مكان آمن وتأكد من إمكانية الوصول إلى رقم الهاتف المسجّل عند الحاجة إلى التحقق.', 1, true
where not exists (select 1 from public.student_guides where title = 'تعليمات تسجيل طالب جديد');

update public.student_guides set details = 'قبل موعد الامتحان، تأكد من استقرار اتصال الإنترنت وشحن الجهاز، واختبر الكاميرا والميكروفون والسماح باستخدامهما من المتصفح. استخدم متصفحاً حديثاً وأغلق التطبيقات والنوافذ غير الضرورية، واجلس في مكان هادئ ومضاء جيداً. ادخل إلى بوابة الامتحانات ببياناتك الصحيحة قبل الموعد بوقت كافٍ، واتبع خطوات التحقق من الهوية وجاهزية الجهاز كما تظهر على الشاشة. اقرأ تعليمات الامتحان قبل البدء، ولا تغلق صفحة الامتحان أو تحدّثها أثناء التقديم إلا إذا وجّهك النظام إلى ذلك. إذا واجهت مشكلة، سجّل وصفها وتواصل مع الدعم الفني دون مشاركة كلمة المرور.', sort_order = 2, is_active = true, updated_at = now() where title = 'كيفية الاستعداد والدخول لتقديم الامتحان';
insert into public.student_guides (title, details, sort_order, is_active)
select 'كيفية الاستعداد والدخول لتقديم الامتحان', 'قبل موعد الامتحان، تأكد من استقرار اتصال الإنترنت وشحن الجهاز، واختبر الكاميرا والميكروفون والسماح باستخدامهما من المتصفح. استخدم متصفحاً حديثاً وأغلق التطبيقات والنوافذ غير الضرورية، واجلس في مكان هادئ ومضاء جيداً. ادخل إلى بوابة الامتحانات ببياناتك الصحيحة قبل الموعد بوقت كافٍ، واتبع خطوات التحقق من الهوية وجاهزية الجهاز كما تظهر على الشاشة. اقرأ تعليمات الامتحان قبل البدء، ولا تغلق صفحة الامتحان أو تحدّثها أثناء التقديم إلا إذا وجّهك النظام إلى ذلك. إذا واجهت مشكلة، سجّل وصفها وتواصل مع الدعم الفني دون مشاركة كلمة المرور.', 2, true
where not exists (select 1 from public.student_guides where title = 'كيفية الاستعداد والدخول لتقديم الامتحان');

update public.student_guides set details = 'افتح خدمة تغيير كلمة المرور من بوابة الطلاب، ثم أدخل البيانات التي يطلبها النظام للتحقق من هويتك. اكتب كلمة مرور جديدة قوية يصعب تخمينها، ويفضّل أن تجمع بين أحرف وأرقام ورموز إذا كان النظام يسمح بذلك. لا تستخدم كلمة مرور سهلة أو مستخدمة في حسابات أخرى، ولا تشاركها مع أي شخص. إذا ظهرت رسالة خطأ، راجع البيانات المدخلة وحاول مرة أخرى؛ وإذا استمرت المشكلة، تواصل مع الدعم الفني واذكر رسالة الخطأ دون إرسال كلمة المرور نفسها.', sort_order = 3, is_active = true, updated_at = now() where title = 'تغيير كلمة المرور';
insert into public.student_guides (title, details, sort_order, is_active)
select 'تغيير كلمة المرور', 'افتح خدمة تغيير كلمة المرور من بوابة الطلاب، ثم أدخل البيانات التي يطلبها النظام للتحقق من هويتك. اكتب كلمة مرور جديدة قوية يصعب تخمينها، ويفضّل أن تجمع بين أحرف وأرقام ورموز إذا كان النظام يسمح بذلك. لا تستخدم كلمة مرور سهلة أو مستخدمة في حسابات أخرى، ولا تشاركها مع أي شخص. إذا ظهرت رسالة خطأ، راجع البيانات المدخلة وحاول مرة أخرى؛ وإذا استمرت المشكلة، تواصل مع الدعم الفني واذكر رسالة الخطأ دون إرسال كلمة المرور نفسها.', 3, true
where not exists (select 1 from public.student_guides where title = 'تغيير كلمة المرور');

update public.student_guides set details = 'افتح صفحة عرض النتائج والشهادات المدرسية من الصفحة الرئيسية. أدخل رقم الجلوس أو البيانات المطلوبة بدقة، ثم اضغط زر عرض النتيجة وانتظر ظهور البيانات. تأكد من صحة رقم الجلوس قبل إعادة المحاولة. إذا لم تظهر النتيجة، فقد تكون غير منشورة بعد أو قد تحتاج البيانات إلى مراجعة؛ تواصل مع الدعم الفني واذكر رقم الجلوس والمشكلة فقط، ولا تنشر بياناتك الشخصية في مكان عام.', sort_order = 4, is_active = true, updated_at = now() where title = 'معرفة النتيجة';
insert into public.student_guides (title, details, sort_order, is_active)
select 'معرفة النتيجة', 'افتح صفحة عرض النتائج والشهادات المدرسية من الصفحة الرئيسية. أدخل رقم الجلوس أو البيانات المطلوبة بدقة، ثم اضغط زر عرض النتيجة وانتظر ظهور البيانات. تأكد من صحة رقم الجلوس قبل إعادة المحاولة. إذا لم تظهر النتيجة، فقد تكون غير منشورة بعد أو قد تحتاج البيانات إلى مراجعة؛ تواصل مع الدعم الفني واذكر رقم الجلوس والمشكلة فقط، ولا تنشر بياناتك الشخصية في مكان عام.', 4, true
where not exists (select 1 from public.student_guides where title = 'معرفة النتيجة');

update public.student_guides set details = 'اختر أيقونة الدعم الفني وحدد نوع المشكلة، ثم اكتب وصفاً واضحاً يتضمن ما كنت تحاول فعله، والخطوة التي توقفت عندها، وأي رسالة خطأ ظهرت. يمكنك إرفاق صورة للشاشة إذا كانت تساعد في شرح المشكلة، مع إخفاء أي معلومات سرية غير لازمة. لا ترفق كلمة المرور أو رموز التحقق. بعد إرسال الطلب، احتفظ برقم المتابعة إن ظهر، وراجع صندوق الرسائل لمعرفة رد فريق الدعم. إذا كنت غير مسجّل وتواجه مشكلة في التسجيل أو نسيت رقم الجلوس، استخدم مسار الدعم المخصص لهذه الحالات واتبع خطوات التحقق المعروضة.', sort_order = 5, is_active = true, updated_at = now() where title = 'التواصل مع الدعم الفني';
insert into public.student_guides (title, details, sort_order, is_active)
select 'التواصل مع الدعم الفني', 'اختر أيقونة الدعم الفني وحدد نوع المشكلة، ثم اكتب وصفاً واضحاً يتضمن ما كنت تحاول فعله، والخطوة التي توقفت عندها، وأي رسالة خطأ ظهرت. يمكنك إرفاق صورة للشاشة إذا كانت تساعد في شرح المشكلة، مع إخفاء أي معلومات سرية غير لازمة. لا ترفق كلمة المرور أو رموز التحقق. بعد إرسال الطلب، احتفظ برقم المتابعة إن ظهر، وراجع صندوق الرسائل لمعرفة رد فريق الدعم. إذا كنت غير مسجّل وتواجه مشكلة في التسجيل أو نسيت رقم الجلوس، استخدم مسار الدعم المخصص لهذه الحالات واتبع خطوات التحقق المعروضة.', 5, true
where not exists (select 1 from public.student_guides where title = 'التواصل مع الدعم الفني');

